function hierarchy(items){let byParent=new Map(),ids=new Set(items.map(x=>x.id));items.forEach(x=>{let key=ids.has(x.parentId)?x.parentId:'';if(!byParent.has(key))byParent.set(key,[]);byParent.get(key).push(x)});let out=[],seen=new Set();function add(parent,depth){(byParent.get(parent)||[]).forEach(x=>{if(seen.has(x.id))return;seen.add(x.id);out.push({...x,_depth:depth});add(x.id,depth+1)})}add('',0);items.forEach(x=>{if(!seen.has(x.id))out.push({...x,_depth:0})});return out}
function listPage(type){if(type==='parts')return partsListPage();let arr=type==='projects'?hierarchy(data.projects):data[type],q=$('#globalSearch').value.trim().toLowerCase();if(q)arr=arr.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q));if(filter!=='Tous')arr=arr.filter(x=>x.status===filter||x.level===filter);return `<div class="toolbar"><div class="filter-group">${options[type].map(x=>`<button class="filter ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><span class="sub">${arr.length} enregistrement${arr.length>1?'s':''}</span></div><div class="table-wrap"><table><thead><tr>${defs[type].headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${arr.length?arr.map(x=>`<tr class="${x._depth?'child-row':''}">${defs[type].row(x)}<td class="row-actions">${type==='projects'?`<button class="log-btn" data-log-project="${x.id}">Journal</button>`:''}<button class="edit-btn" data-edit="${x.id}" data-type="${type}">Modifier</button><button data-delete="${x.id}" data-type="${type}">Supprimer</button></td></tr>`).join(''):`<tr><td colspan="12" class="empty">Aucun enregistrement correspondant</td></tr>`}</tbody></table></div>`}
function partsListPage(){let q=$('#globalSearch').value.trim().toLowerCase(),materialsInUse=[...new Set(data.parts.map(p=>p.material).filter(Boolean))].sort(),thicknesses=[...new Set(data.parts.map(p=>Number(p.thickness||0)))].sort((a,b)=>a-b),arr=data.parts.filter(p=>(!q||Object.values(p).join(' ').toLowerCase().includes(q))&&(partFamilyFilter==='Toutes'||partFamily(p)===partFamilyFilter)&&(partMaterialFilter==='Toutes'||p.material===partMaterialFilter)&&(partThicknessFilter==='Toutes'||String(Number(p.thickness||0))===partThicknessFilter));return `<div class="parts-filter-panel"><div class="filter-group family-filters"><button class="filter ${partFamilyFilter==='Toutes'?'active':''}" data-part-family="Toutes">Toutes les familles</button>${partFamilies.map(f=>`<button class="filter ${partFamilyFilter===f?'active':''}" data-part-family="${f}">${f}</button>`).join('')}</div><div class="parts-select-filters"><label>Matière<select data-part-material><option>Toutes</option>${materialsInUse.map(m=>`<option ${partMaterialFilter===m?'selected':''}>${m}</option>`).join('')}</select></label><label>Épaisseur<select data-part-thickness><option value="Toutes">Toutes</option>${thicknesses.map(t=>`<option value="${t}" ${partThicknessFilter===String(t)?'selected':''}>${t} mm</option>`).join('')}</select></label><button class="clear-parts-filter" data-clear-parts-filter>Réinitialiser</button><span>${arr.length} pièce${arr.length>1?'s':''}</span></div></div><div class="table-wrap"><table><thead><tr>${defs.parts.headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${arr.length?arr.map(x=>`<tr>${defs.parts.row(x)}<td class="row-actions"><button class="edit-btn" data-edit="${x.id}" data-type="parts">Modifier</button><button data-delete="${x.id}" data-type="parts">Supprimer</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty">Aucune pièce ne correspond aux filtres.</td></tr>'}</tbody></table></div>`}
function reports(){let total=data.repairs.reduce((s,x)=>s+Number(x.cost),0),purchase=data.purchases.reduce((s,x)=>s+Number(x.qty)*Number(x.price),0),months=[38,52,31,64,45,72];return `${stats()}<div class="report-grid"><section class="card"><div class="card-head"><div><h3>Coûts de réparation · 6 mois</h3><span class="sub">Indice mensuel</span></div><b>${money(total)}</b></div><div class="chart">${months.map((v,i)=>`<div class="bar-wrap"><div class="bar" data-value="${v}" style="height:${v}%"></div><div class="bar-label">${['Mars','Avr.','Mai','Juin','Juil.','Août'][i]}</div></div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Répartition des causes</h3></div><div class="donut-wrap"><div class="donut"></div><div class="legend">${[['Usure',42,'green'],['Rupture',26,'orange'],['Ébréchure',16,'red'],['Autres',16,'blue']].map(x=>`<div class="legend-item"><i style="background:var(--${x[2]})"></i><span>${x[0]}</span><b>${x[1]}%</b></div>`).join('')}</div></div></section></div><section class="card insight"><div><h3>Analyse</h3><p>Les poinçons et broches représentent <strong>58 %</strong> des dommages. Renforcez leur contrôle préventif et constituez un stock de sécurité.</p></div><div><span class="sub" style="color:#a9c1b5">Montant des achats</span><b style="font-size:20px">${money(purchase)}</b></div></section>`}
const addDays=(date,n)=>{let d=new Date(date||'2026-08-01');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
reports=()=>{let projectDone=data.projects.filter(p=>p.status==='Validé').length,projectActive=data.projects.length-projectDone,broken=data.moulds.filter(m=>m.status==='Panne').length,repairActive=data.repairs.filter(r=>r.status!=='Terminé').length,repairDone=data.repairs.filter(r=>r.status==='Terminé').length,activePurchases=data.purchases.filter(p=>p.status!=='Terminé'),partsToBuy=activePurchases.reduce((sum,p)=>sum+(p.components||[]).reduce((s,c)=>s+Number(c.qty||0),0),0),budget=activePurchases.reduce((sum,p)=>sum+(p.components||[]).reduce((s,c)=>s+Number(c.qty||0)*Number(c.price||0),0),0),today=new Date().toISOString().slice(0,10),urgent=[...data.projects.filter(p=>p.priority==='Urgent'&&p.status!=='Validé').map(p=>({id:p.id,name:p.name,type:'Fabrication',start:p.start||p.created||today,end:p.due||today})),...data.repairs.filter(r=>r.urgency==='Urgent'&&r.status!=='Terminé').map(r=>({id:r.id,name:r.issue||r.mould||'Réparation',type:'Réparation',start:r.date||today,end:addDays(r.date||today,7)})),...activePurchases.filter(p=>p.urgency==='Urgent').map(p=>({id:p.id,name:p.supplier||'Commande',type:'Achat',start:today,end:p.eta||addDays(today,14)}))],dates=urgent.flatMap(x=>[new Date(x.start),new Date(x.end)]),min=dates.length?Math.min(...dates):Date.now(),max=dates.length?Math.max(...dates):min+86400000,range=Math.max(86400000,max-min);return `<section class="report-kpis">${[[data.projects.length,'Projets de moules','Total'],[projectActive,'En cours',projectDone+' terminés'],[broken,'Moules en panne',repairActive+' réparations en cours'],[repairDone,'Réparations terminées','Historique clôturé'],[data.purchases.length,'Bons d’achat',partsToBuy+' pièces à acheter'],[money(budget),'Budget achats','Commandes en cours']].map((x,i)=>`<div class="card report-kpi tone-${i}"><span>${x[1]}</span><b>${x[0]}</b><small>${x[2]}</small></div>`).join('')}</section><section class="card gantt-card"><div class="card-head"><div><span class="section-kicker">PLANIFICATION PRIORITAIRE</span><h3>Gantt des dossiers urgents</h3><span class="sub">Fabrications, réparations et achats classés Urgent</span></div>${urgencyBadge('Urgent')}</div><div class="gantt-head"><span>Dossier</span><span>Calendrier</span></div><div class="gantt-list">${urgent.length?urgent.map(x=>{let left=Math.max(0,(new Date(x.start)-min)/range*82),width=Math.max(8,(new Date(x.end)-new Date(x.start))/range*82);return `<div class="gantt-row"><div><b>${x.id}</b><span>${x.type} · ${x.name}</span></div><div class="gantt-track"><span class="gantt-bar gantt-${x.type.toLowerCase().replace('é','e')}" style="left:${left}%;width:${Math.min(width,100-left)}%"><small>${x.start} → ${x.end}</small></span></div></div>`}).join(''):'<div class="empty">Aucun dossier urgent en cours.</div>'}</div></section>`};
const stageDefinitions=[['amont','AMONT',0,5],['conception','CONCEPTION',5,15],['drawing','MISE EN PLAN',15,23],['machining','USINAGE',23,43],['trial','MISE AU PLAN ET ESSAI',43,53],['validated','VALIDÉ',53,55]];const reportsWithMouldNames=reports;reports=()=>{let html=reportsWithMouldNames(),mouldLabel=id=>{let m=data.moulds.find(x=>x.id===id);return m?`${m.id} · ${m.name}`:'Aucun moule associé'};data.projects.filter(p=>p.priority==='Urgent'&&p.status!=='Validé').forEach(p=>{let moulds=data.moulds.filter(m=>m.project===p.id).map(m=>`${m.id} · ${m.name}`).join(', ')||'Aucun moule associé';html=html.replace(`<span>Fabrication · ${p.name}</span>`,`<span>Fabrication · ${p.name}</span><small class="gantt-mould">Moule associé : ${moulds}</small>`)});data.repairs.filter(r=>r.urgency==='Urgent'&&r.status!=='Terminé').forEach(r=>{let name=r.issue||r.mould||'Réparation';html=html.replace(`<span>Réparation · ${name}</span>`,`<span>Réparation · ${name}</span><small class="gantt-mould">Moule associé : ${mouldLabel(r.mould)}</small>`)});data.purchases.filter(p=>p.urgency==='Urgent'&&p.status!=='Terminé').forEach(p=>{let name=p.supplier||'Commande';html=html.replace(`<span>Achat · ${name}</span>`,`<span>Achat · ${name}</span><small class="gantt-mould">Moule associé : ${mouldLabel(p.mould)}</small>`)});return html};
function projectDetail(){let p=data.projects.find(x=>x.id===selectedProjectId);if(!p)return listPage('projects');let start=p.start||p.created||'2026-08-01',created=p.created||start,current=projectStatuses.indexOf(p.status);return `<button class="back-btn" data-back-projects>← Retour à 模具制造</button><section class="project-hero card"><div><span class="eyebrow">${p.id}${p.parentId?` · Sous-projet de ${p.parentId}`:''}</span><h2>${p.name}</h2><p>${p.customer} · Responsable : ${p.owner}</p></div><div class="project-progress"><b>${p.progress}%</b><span>Avancement global</span></div></section><div class="detail-stats"><div class="card"><span>Créé le</span><b>${created}</b></div><div class="card"><span>Début du projet</span><b>${start}</b></div><div class="card"><span>Échéance finale</span><b>${p.due||'—'}</b></div><div class="card project-status-card"><span>Statut actuel · modifiable</span>${projectStatusSelect(p)}</div></div><section class="card workflow-card"><div class="card-head"><div><h3>Étapes de fabrication</h3><span class="sub">Le workflow suit automatiquement le statut sélectionné</span></div><button class="secondary" data-edit-project="${p.id}">Modifier la fabrication</button></div><div class="workflow workflow-six">${stageDefinitions.map((s,i)=>{let detail=p.stageDetails?.[s[0]]||{},from=detail.start||addDays(start,s[2]),to=detail.end||addDays(start,s[3]),state=i<current?'done':i===current?'active':'pending',days=Math.max(1,Math.round((new Date(to)-new Date(from))/86400000));return `<button class="workflow-step ${state}" data-stage="${s[0]}"><div class="step-marker">${state==='done'?'✓':i+1}</div><div class="step-body"><div><h4>${s[1]}</h4><span>${state==='done'?'Terminée':state==='active'?'En cours':'À venir'}</span></div><p>${from} → ${to}</p><small>${detail.duration||days+' jours'}${detail.participants?` · ${detail.participants}`:''}</small></div></button>`}).join('')}</div></section>`}
function projectLogSection(){let project=data.projects.find(p=>p.id===selectedProjectId),logs=(project?.workLogs||[]).slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)));return `<section class="card project-log-card"><div class="card-head"><div><span class="section-kicker">Suivi quotidien</span><h3>Journal de travail</h3><span class="sub">Avancement, travail réalisé et points bloquants</span></div><button class="primary" data-log-project="${project.id}">＋ Ajouter le journal du jour</button></div><div class="log-list">${logs.length?logs.map(log=>{let resolved=log.blockerStatus==='Résolu';return `<article class="log-entry"><div class="log-date"><b>${log.date}</b>${badge(log.status)}<div class="log-actions"><button class="edit-log" data-edit-log="${log.id}" data-log-project-id="${project.id}">Modifier</button><button class="delete-log" data-delete-log="${log.id}" data-log-project-id="${project.id}">Supprimer</button></div></div><div><span>Travail réalisé</span><p>${log.work}</p></div><div class="log-blocker ${log.blocker?(resolved?'resolved':'active'):''}"><span>Point bloquant · ${resolved?'Résolu':'En attente de résolution'}</span><p>${log.blocker||'Aucun blocage'}</p></div></article>`}).join(''):'<div class="empty">Aucun journal de travail pour ce projet.</div>'}</div></section>`}
function projectRelations(){let p=data.projects.find(x=>x.id===selectedProjectId);return `<section class="card relation-card"><div class="card-head"><div><span class="section-kicker">Relations</span><h3>Type et pièces du projet</h3></div></div><div class="relation-summary"><div><span>Type de fabrication</span><b>${p.mouldType||'—'}</b></div><div><span>Pièces associées</span><div>${(p.linkedPartIds||[]).map(id=>`<button class="relation-chip" data-part-link="${id}">${id}</button>`).join('')||'Aucune pièce associée'}</div></div></div></section>`}
const projectDetailBase=projectDetail;projectDetail=()=>projectDetailBase().replaceAll('模具制造','Fabrication de moules')+projectRelations()+projectLogSection();
function partDashboard(){let p=data.parts.find(x=>x.id===selectedPartId),moulds=data.moulds.filter(m=>(p?.relatedMouldIds||[]).includes(m.id));if(!p)return listPage('parts');return `<button class="back-btn" data-back-parts>← Retour au catalogue</button><section class="project-hero card"><div><span class="eyebrow">${p.id} · ${partFamily(p)||'À classer'}</span><h2>${p.name}</h2><p>${p.material} · ${p.thickness} mm</p></div><button class="secondary" data-edit="${p.id}" data-type="parts">Modifier la pièce</button></section><div class="detail-stats"><div class="card"><span>Famille</span><b>${partFamily(p)||'À classer'}</b></div><div class="card"><span>Matière</span><b>${p.material}</b></div><div class="card"><span>Épaisseur</span><b>${p.thickness} mm</b></div><div class="card"><span>Moules associés</span><b>${moulds.length}</b></div></div><section class="card relation-card"><div class="card-head"><h3>Moules associés</h3></div><div class="relation-grid">${moulds.length?moulds.map(m=>`<button class="relation-tile" data-mould-link="${m.id}"><b>${m.id}</b><span>${m.name}</span><small>${m.mouldCategory} · ${m.status}</small></button>`).join(''):'<div class="empty">Aucun moule associé</div>'}</div></section>`}
function mouldDashboard(){let m=data.moulds.find(x=>x.id===selectedMouldId),parts=data.parts.filter(p=>(m?.linkedPartIds||[]).includes(p.id));if(!m)return listPage('moulds');return `<button class="back-btn" data-back-moulds>← Retour au parc</button><section class="project-hero card"><div><span class="eyebrow">${m.id}</span><h2>${m.name}</h2><p>${m.mouldCategory} · ${m.type}</p></div><button class="secondary" data-edit="${m.id}" data-type="moulds">Modifier le moule</button></section><div class="detail-stats"><div class="card"><span>Statut</span>${badge(m.status)}</div><div class="card"><span>Projet lié</span>${m.project?`<button class="relation-link" data-project="${m.project}">${m.project}</button>`:'—'}</div><div class="card"><span>Pièces associées</span><b>${parts.length}</b></div><div class="card"><span>Utilisation</span><b>${m.utilization||0} %</b></div></div><section class="card relation-card"><div class="card-head"><h3>Pièces associées</h3></div><div class="relation-grid">${parts.length?parts.map(p=>`<button class="relation-tile" data-part-link="${p.id}"><b>${p.id}</b><span>${p.name}</span><small>${p.material} · ${p.thickness} mm</small></button>`).join(''):'<div class="empty">Aucune pièce associée</div>'}</div></section>`}
function openProjectLog(projectId,logId=''){let project=data.projects.find(p=>p.id===projectId),log=(project?.workLogs||[]).find(x=>x.id===logId);if(!project)return;$('#modalTitle').textContent=`${log?'Modifier le journal':'Journal'} · ${project.id}`;$('#modalEyebrow').textContent=log?'MODIFICATION DU JOURNAL':'MISE À JOUR DU PROJET';$('#entityForm').dataset.type='projectLog';$('#entityForm').dataset.editId=project.id;$('#entityForm').dataset.logId=log?.id||'';$('#formFields').innerHTML=`<div class="field"><label>Date</label><input name="date" type="date" value="${log?.date||new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Statut du projet</label><select name="status" required>${projectStatuses.map(s=>`<option ${s===(log?.status||project.status)?'selected':''}>${s}</option>`).join('')}</select></div><div class="field full"><label>Travail réalisé aujourd’hui</label><textarea name="work" placeholder="Décrivez les opérations effectuées, décisions et résultats..." required>${log?.work||''}</textarea></div><div class="field"><label>Statut du point bloquant</label><select name="blockerStatus"><option ${log?.blockerStatus!=='Résolu'?'selected':''}>En attente de résolution</option><option ${log?.blockerStatus==='Résolu'?'selected':''}>Résolu</option></select></div><div class="field full"><label>Point bloquant / problème actuel</label><textarea name="blocker" placeholder="Indiquez ce qui bloque le projet. Laissez vide s’il n’y a aucun blocage.">${log?.blocker||''}</textarea></div>`;$('#modalBackdrop').classList.add('open')}
function repairDashboard(){let r=data.repairs.find(x=>x.id===selectedRepairId),purchase=data.purchases.find(p=>p.repairId===r?.id),mould=data.moulds.find(m=>m.id===r?.mould);if(!r)return listPage('repairs');return `<button class="back-btn" data-back-repairs>← Retour aux réparations</button><section class="project-hero card"><div><span class="eyebrow">${r.id}</span><h2>Panne · ${mould?.name||r.mould||'Moule non associé'}</h2><p>${r.issue||'Sans description'}</p></div><button class="secondary" data-edit="${r.id}" data-type="repairs">Modifier la réparation</button></section><div class="detail-stats"><div class="card"><span>Statut</span>${badge(r.status)}</div><div class="card"><span>Moule associé</span>${r.mould?`<button class="relation-link mould-name-link" data-mould-link="${r.mould}"><b>${r.mould}</b><span>${mould?.name||'Nom du moule à renseigner'}</span></button>`:'Aucun moule associé'}</div><div class="card"><span>Gravité</span>${badge(r.level)}</div><div class="card"><span>Coût estimé</span><b>${money(r.cost)}</b></div></div><section class="card relation-card"><div class="card-head"><h3>Composants endommagés</h3>${purchase?`<button class="relation-chip" data-purchase-link="${purchase.id}">Achat ${purchase.id}</button>`:''}</div><div class="relation-grid">${(r.components||[]).map(c=>`<div class="relation-tile"><b>${c.name}</b><span>${c.qty} pièce(s)</span><small>${c.material}${c.heatTreated?' · traitement thermique':''}</small></div>`).join('')||'<div class="empty">Aucun composant renseigné</div>'}</div></section>`}
function purchaseDashboard(){let p=data.purchases.find(x=>x.id===selectedPurchaseId),total=p?.components?.reduce((sum,c)=>sum+Number(c.qty)*Number(c.price),0)||0,mould=data.moulds.find(m=>m.id===p?.mould);if(!p)return listPage('purchases');return `<button class="back-btn" data-back-purchases>← Retour aux achats</button><section class="project-hero card"><div><span class="eyebrow">${p.id}</span><h2>Commande d’achat</h2><p>${p.supplier||'Fournisseur à définir'} · ${p.drawing||'Plan à renseigner'}</p></div><button class="secondary" data-edit="${p.id}" data-type="purchases">Modifier l’achat</button></section><div class="detail-stats"><div class="card"><span>Statut</span>${badge(p.status)}</div><div class="card"><span>Moule associé</span>${p.mould?`<button class="relation-link mould-name-link" data-mould-link="${p.mould}"><b>${p.mould}</b><span>${mould?.name||'Nom du moule à renseigner'}</span></button>`:'Aucun moule associé'}</div><div class="card"><span>Réparation liée</span>${p.repairId?`<button class="relation-link" data-repair-link="${p.repairId}">${p.repairId}</button>`:'—'}</div><div class="card"><span>Montant total</span><b>${money(total)}</b></div></div><section class="card relation-card"><div class="card-head"><h3>Composants achetés</h3></div><div class="relation-grid">${(p.components||[]).map(c=>`<div class="relation-tile"><b>${c.name}</b><span>${c.qty} × ${money(c.price)}</span><small>${c.material}${c.heatTreated?' · traitement thermique':''}</small></div>`).join('')||'<div class="empty">Aucun composant renseigné</div>'}</div></section>`}
