function dashboardActivity(){let entries=[];data.projects.forEach(p=>{if(p.created)entries.push({date:p.created,type:'new',project:p,title:'Nouveau projet ajouté',text:`${p.id} · ${p.name}`});let log=latestProjectLog(p);if(log)entries.push({date:log.date,type:'log',project:p,log,title:'Journal de travail mis à jour',text:`${p.id} · ${log.work||'Mise à jour du projet'}`})});entries.sort((a,b)=>String(b.date).localeCompare(String(a.date)));return `<section class="card activity-card"><div class="card-head"><div><span class="section-kicker">DERNIÈRES MISES À JOUR</span><h3>Activité récente</h3></div><span class="live-dot">En direct</span></div><div class="timeline dynamic-activity">${entries.slice(0,6).map(e=>`<button class="event activity-event" ${e.type==='log'?`data-journal-project="${e.project.id}"`:`data-project="${e.project.id}"`} style="--dot:${e.type==='log'?'var(--orange)':'var(--green)'}"><h4>${e.title}</h4><p>${e.text}</p><time>${e.date}${e.type==='log'?` · ${e.log.status}`:''}</time></button>`).join('')||'<div class="empty">Aucune activité récente.</div>'}</div></section>`}
