const listPageWithoutJournalAction=listPage;listPage=type=>{let html=listPageWithoutJournalAction(type);return type==='projects'?html.replace(/<button class="log-btn" data-log-project="[^"]+">Journal<\/button>/g,''):html};const reportsWithProjectTracking=reports;reports=()=>{let html=reportsWithProjectTracking(),section=`<section class="card report-projects"><div class="card-head"><div><span class="section-kicker">SUIVI DE FABRICATION</span><h3>État des projets et derniers blocages</h3></div><span class="sub">${data.projects.length} projet(s)</span></div><div class="table-wrap"><table><thead><tr><th>Projet</th><th>Statut</th><th>Avancement</th><th>Urgence</th><th>Dernier blocage</th><th>Mise à jour</th></tr></thead><tbody>${data.projects.map(p=>{let log=latestProjectLog(p),resolved=log?.blockerStatus==='Résolu';return `<tr><td><button class="relation-link" data-project="${p.id}"><b>${p.id}</b></button><span class="sub">${p.name}</span></td><td>${badge(p.status)}</td><td>${progress(p.progress)}</td><td>${urgencyBadge(p.priority)}</td><td class="blocker-cell ${resolved?'resolved':log?.blocker?'has-blocker':''}">${log?.blocker||'Aucun blocage'}${log?.blocker?`<small class="blocker-state">${log.blockerStatus}</small>`:''}</td><td>${log?.date||'—'}</td></tr>`}).join('')}</tbody></table></div></section>`;return html.replace('<section class="card gantt-card">',section+'<section class="card gantt-card">')};
