const nextRepairId=()=>{let max=data.repairs.reduce((n,x)=>Math.max(n,Number(String(x.id).match(/\d+/)?.[0]||0)),0);return `WX-${String(max+1).padStart(4,'0')}`};
function ensureMouldRepair(mould){if(mould.status!=='Panne'||data.repairs.some(r=>r.mould===mould.id&&r.status!=='Terminé'))return false;data.repairs.unshift({id:nextRepairId(),mould:mould.id,components:[],componentCount:1,issue:'Panne signalée depuis le parc de moules',level:'Modérée',owner:'XING ZHAO',status:'À traiter',date:new Date().toISOString().slice(0,10),cost:0});return true}
function ensureRepairPurchases(repair){let actionFields=[...document.querySelectorAll('#componentRows select[name^="compAction"]')];repair.components=(repair.components||[]).map((c,i)=>({...c,action:actionFields[i]?.value||c.action||'Réparation'}));let components=repair.components.filter(c=>c.action==='Achat').map(c=>({...c,price:0})),existing=data.purchases.find(p=>p.repairId===repair.id);if(!components.length){if(existing?.autoCreated)data.purchases=data.purchases.filter(p=>p!==existing);return false}let mould=data.moulds.find(m=>m.id===repair.mould),summary=components.map(c=>`${c.name} × ${c.qty} · ${c.material}${c.heatTreated?' · traitement thermique':''}`).join(' / ');if(existing){existing.mould=repair.mould;existing.project=mould?.project||'';existing.components=components;existing.componentCount=components.length;existing.part=summary;return false}data.purchases.unshift({id:nextPurchaseId(),repairId:repair.id,mould:repair.mould,project:mould?.project||'',components,componentCount:components.length,part:summary,drawing:'À renseigner',supplier:'À définir',status:'En consultation',eta:'',autoCreated:true});return true}
function openModal(type,record=null){let titles={projects:'Nouvelle fabrication',moulds:'Ajouter un moule',repairs:'Signaler une panne',purchases:'Nouvel achat'},editTitles={projects:'Modifier la fabrication',moulds:'Modifier le moule',repairs:'Modifier la réparation',purchases:'Modifier l’achat'};$('#modalTitle').textContent=record?editTitles[type]:titles[type];$('#modalEyebrow').textContent=record?'MODIFICATION':'NOUVEAU';$('#entityForm').dataset.type=type;$('#entityForm').dataset.editId=record?.id||'';$('#formFields').innerHTML=fields[type].filter(([key])=>type!=='projects'||!hiddenProjectFields.has(key)).map(([key,label,t,opt])=>{let control=t==='select'?`<select name="${key}" required>${opt.map(v=>`<option>${v}</option>`).join('')}</select>`:t==='project-parent'?`<select name="${key}"><option value="">Aucun · projet principal</option>${data.projects.filter(p=>p.id!==record?.id).map(p=>`<option value="${p.id}">${p.id} · ${p.name}</option>`).join('')}</select>`:`<input name="${key}" type="${t}" placeholder="${opt}" ${['id','name','part'].includes(key)?'required':''}>`;return `<div class="field"><label>${label}</label>${control}</div>`}).join('');if(record)Object.entries(record).forEach(([key,value])=>{let field=$('#entityForm').elements.namedItem(key);if(field)field.value=value});$('#modalBackdrop').classList.add('open')}
function openStageModal(key){let p=data.projects.find(x=>x.id===selectedProjectId),stage=stageDefinitions.find(x=>x[0]===key),detail=p?.stageDetails?.[key]||{};if(!p||!stage)return;$('#modalTitle').textContent=stage[1];$('#modalEyebrow').textContent='DÉTAIL DE L’ÉTAPE';$('#entityForm').dataset.type='stage';$('#entityForm').dataset.editId=key;$('#formFields').innerHTML=`<div class="field"><label>Date de début</label><input name="start" type="date" value="${detail.start||''}"></div><div class="field"><label>Date de fin</label><input name="end" type="date" value="${detail.end||''}"></div><div class="field"><label>Temps de travail</label><input name="duration" type="text" value="${detail.duration||''}" placeholder="Ex. 12 jours / 80 heures"></div><div class="field"><label>Participants</label><input name="participants" type="text" value="${detail.participants||''}" placeholder="XING ZHAO, fournisseur..."></div><div class="field full"><label>Remarques</label><textarea name="notes" placeholder="Informations, décisions et points de vigilance">${detail.notes||''}</textarea></div>`;$('#modalBackdrop').classList.add('open')}
const componentRows=(count,values=[])=>Array.from({length:Math.max(1,Number(count)||1)},(_,i)=>{let c=values[i]||{},actions=['Achat','Remplacement','Réparation'];return `<div class="component-line"><b>Composant ${i+1}</b><input name="compName${i}" value="${c.name||''}" placeholder="Nom" required><input name="compQty${i}" type="number" min="1" value="${c.qty||1}" placeholder="Quantité" required><input name="compMaterial${i}" value="${c.material||''}" placeholder="Matière" required><label class="heat-check"><input name="compHeat${i}" type="checkbox" ${c.heatTreated?'checked':''}> Traitement thermique</label><select name="compAction${i}" aria-label="Action pour le composant">${actions.map(action=>`<option ${action===(c.action||'Réparation')?'selected':''}>${action}</option>`).join('')}</select><button type="button" class="remove-component" data-remove-repair-component title="Supprimer ce composant">Supprimer</button></div>`}).join('');
