const openModalBase=openModal;openModal=(type,record=null)=>{if(type==='repairs')repairMouldField[3]=data.moulds.map(m=>m.id);if(type==='purchases')purchaseMouldField[3]=data.moulds.map(m=>m.id);openModalBase(type,record);if(type==='projects'){if(!record)$('#entityForm').elements.namedItem('owner').value='XING ZHAO';mountMultiSelect('linkedPartIds',data.parts,record?.linkedPartIds||[])}if(type==='parts'){$('#modalTitle').textContent=record?'Modifier la pièce':'Ajouter une pièce';let familyField=$('#entityForm').elements.namedItem('family');if(record&&partFamily(record))familyField.value=partFamily(record);$('#entityForm').elements.namedItem('thickness').step='any';mountMultiSelect('relatedMouldIds',data.moulds,record?.relatedMouldIds||[])}if(type==='moulds'){$('#entityForm').elements.namedItem('maxThickness').step='any';mountMultiSelect('linkedPartIds',data.parts,record?.linkedPartIds||[])}if(type==='repairs'){let source=$('#entityForm').elements.namedItem('components'),host=source.parentElement,count=$('#entityForm').elements.namedItem('componentCount');host.classList.add('full');source.remove();host.insertAdjacentHTML('beforeend','<div id="componentRows"></div>');let draw=()=>{$('#componentRows').innerHTML=componentRows(count.value,record?.components||[])};count.value=record?.components?.length||record?.componentCount||1;count.oninput=draw;draw()}if(type==='purchases'){let source=$('#entityForm').elements.namedItem('components'),host=source.parentElement,count=$('#entityForm').elements.namedItem('componentCount'),repair=data.repairs.find(r=>r.id===record?.repairId);host.classList.add('full');source.remove();host.insertAdjacentHTML('beforeend','<div id="purchaseRows"></div>');let values=record?.components?.length?record.components:repair?.components?.length?repair.components.map(c=>({...c,price:0})):[{name:record?.part||'',qty:record?.qty||1,material:'',heatTreated:false,price:record?.price||0}],draw=()=>{$('#purchaseRows').innerHTML=purchaseRows(count.value,values)};count.value=values.length;count.oninput=draw;draw()}};
