content.onclick=e=>{let deleteLog=e.target.closest('[data-delete-log]');if(deleteLog){if(confirm('Supprimer ce journal de travail ?')){let project=data.projects.find(p=>p.id===deleteLog.dataset.logProjectId);if(project){project.workLogs=(project.workLogs||[]).filter(log=>log.id!==deleteLog.dataset.deleteLog);save();render();toast('Journal supprimé')}}return}let partLink=e.target.closest('[data-part-link]');if(partLink){selectedPartId=partLink.dataset.partLink;view='partDetail';render();return}let mouldLink=e.target.closest('[data-mould-link]');if(mouldLink){selectedMouldId=mouldLink.dataset.mouldLink;view='mouldDetail';render();return}if(e.target.closest('[data-back-parts]')){view='parts';selectedPartId=null;render();return}if(e.target.closest('[data-back-moulds]')){view='moulds';selectedMouldId=null;render();return}let log=e.target.closest('[data-log-project]');if(log){openProjectLog(log.dataset.logProject);return}let stage=e.target.closest('[data-stage]');if(stage){openStageModal(stage.dataset.stage);return}let project=e.target.closest('[data-project]');if(project){selectedProjectId=project.dataset.project;view='projectDetail';render();return}let back=e.target.closest('[data-back-projects]');if(back){view='projects';selectedProjectId=null;render();return}let plan=e.target.closest('[data-edit-project]');if(plan){let record=data.projects.find(x=>x.id===plan.dataset.editProject);if(record)openModal('projects',record);return}let go=e.target.closest('[data-go]');if(go){view=go.dataset.go;filter='Tous';render()}let f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render()}let edit=e.target.closest('[data-edit]');if(edit){let record=data[edit.dataset.type].find(x=>x.id===edit.dataset.edit);if(record)openModal(edit.dataset.type,record)}let d=e.target.closest('[data-delete]');if(d&&confirm('Supprimer cet enregistrement ?')){if(d.dataset.type==='projects')data.projects.forEach(p=>{if(p.parentId===d.dataset.delete)p.parentId='' });data[d.dataset.type]=data[d.dataset.type].filter(x=>x.id!==d.dataset.delete);save();render();toast('Enregistrement supprimé')}};
content.onchange=e=>{let select=e.target.closest('.status-select');if(!select)return;if(select.dataset.statusProject){let project=data.projects.find(p=>p.id===select.dataset.statusProject);project.status=select.value;project.progress=projectProgress[select.value];let created=ensureSupplierPurchase(project);save();render();toast(created?'Statut mis à jour · commande d’achat créée':`Avancement mis à jour : ${project.progress}%`);return}if(select.dataset.mouldStatus){let mould=data.moulds.find(m=>m.id===select.dataset.mouldStatus);mould.status=select.value;let created=ensureMouldRepair(mould);save();render();toast(created?'Panne enregistrée · fiche de réparation créée':'Statut du moule mis à jour');return}if(select.dataset.repairStatus){let repair=data.repairs.find(r=>r.id===select.dataset.repairStatus);repair.status=select.value;let created=ensureRepairPurchases(repair);if(repair.status==='Terminé'){let mould=data.moulds.find(m=>m.id===repair.mould);if(mould)mould.status='Dispo'}save();render();toast(created?'Commande d’achat créée automatiquement':repair.status==='Terminé'?'Réparation terminée · moule disponible':'Statut de réparation mis à jour');return}if(select.dataset.purchaseStatus){let purchase=data.purchases.find(p=>p.id===select.dataset.purchaseStatus);purchase.status=select.value;if(purchase.status==='Terminé'&&purchase.repairId){let linked=data.purchases.filter(p=>p.repairId===purchase.repairId),repair=data.repairs.find(r=>r.id===purchase.repairId);if(repair&&linked.every(p=>p.status==='Terminé'))repair.status='En réparation'}save();render();toast(purchase.status==='Terminé'&&purchase.repairId?'Achat terminé · réparation en cours':'Statut d’achat mis à jour')}};
$('#mainAddBtn').onclick=()=>{if(view==='reports'){window.print();return}if(view==='projectDetail'){let record=data.projects.find(x=>x.id===selectedProjectId);if(record)openModal('projects',record);return}if(view==='partDetail'){let record=data.parts.find(x=>x.id===selectedPartId);if(record)openModal('parts',record);return}if(view==='mouldDetail'){let record=data.moulds.find(x=>x.id===selectedMouldId);if(record)openModal('moulds',record);return}if(view==='repairDetail'){let record=data.repairs.find(x=>x.id===selectedRepairId);if(record)openModal('repairs',record);return}if(view==='purchaseDetail'){let record=data.purchases.find(x=>x.id===selectedPurchaseId);if(record)openModal('purchases',record);return}openModal(view==='dashboard'?'projects':view)};$('#closeModal').onclick=$('#cancelModal').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};
$('#entityForm').addEventListener('submit',e=>{if(e.target.dataset.type!=='projectLog')return;e.preventDefault();e.stopImmediatePropagation();let project=data.projects.find(p=>p.id===e.target.dataset.editId),entry=Object.fromEntries(new FormData(e.target)),logId=e.target.dataset.logId;if(logId){let index=(project.workLogs||[]).findIndex(x=>x.id===logId);if(index!==-1)project.workLogs[index]={...project.workLogs[index],...entry}}else{entry.id=`LOG-${project.id}-${Date.now()}`;project.workLogs=[entry,...(project.workLogs||[])]}project.status=entry.status;project.progress=projectProgress[entry.status];ensureSupplierPurchase(project);save();closeModal();render();toast(logId?'Journal modifié':'Journal de travail ajouté')},true);
$('#entityForm').onsubmit=e=>{e.preventDefault();let type=e.target.dataset.type,editId=e.target.dataset.editId,returnToDetail=view==='projectDetail',form=new FormData(e.target),obj=Object.fromEntries(form);if(type==='stage'){let project=data.projects.find(p=>p.id===selectedProjectId),start=new Date(obj.start),end=new Date(obj.end),days=Math.max(0,Math.round((end-start)/86400000));obj.duration=obj.start&&obj.end&&!Number.isNaN(days)?`${days} jour${days>1?'s':''}`:'';project.stageDetails={...(project.stageDetails||{}),[editId]:obj};save();closeModal();render();toast(`Détails enregistrés${obj.duration?' · '+obj.duration:''}`);return}if(['projects','moulds'].includes(type))obj.linkedPartIds=form.getAll('linkedPartIds');if(type==='parts')obj.relatedMouldIds=form.getAll('relatedMouldIds');if(type==='repairs'){let count=Math.max(1,Number(obj.componentCount)||1);obj.components=Array.from({length:count},(_,i)=>({name:form.get(`compName${i}`)||'',qty:Number(form.get(`compQty${i}`)||1),material:form.get(`compMaterial${i}`)||'Fer',heatTreated:form.has(`compHeat${i}`)}));Object.keys(obj).filter(k=>/^comp(Name|Qty|Material|Heat)/.test(k)).forEach(k=>delete obj[k])}if(type==='purchases'){let count=Math.max(1,Number(obj.componentCount)||1);obj.components=Array.from({length:count},(_,i)=>({name:form.get(`buyName${i}`)||'',qty:Number(form.get(`buyQty${i}`)||1),material:form.get(`buyMaterial${i}`)||'',heatTreated:form.has(`buyHeat${i}`),price:Number(form.get(`buyPrice${i}`)||0)}));obj.part=obj.components.map(c=>c.name).join(' / ');obj.qty=obj.components.reduce((sum,c)=>sum+c.qty,0);obj.price=obj.components.reduce((sum,c)=>sum+c.qty*c.price,0);Object.keys(obj).filter(k=>/^buy(Name|Qty|Material|Heat|Price)/.test(k)).forEach(k=>delete obj[k])}['cycles','piecesPerStroke','stripWidth','maxThickness','utilization','thickness','componentCount','cost','qty','price'].forEach(k=>{if(k in obj)obj[k]=Number(obj[k]||0)});if(type==='projects'){let previous=data.projects.find(x=>x.id===editId);obj.status=previous?.status||'Amont';obj.progress=projectProgress[obj.status]}if(editId){let index=data[type].findIndex(x=>x.id===editId);if(index!==-1)data[type][index]={...data[type][index],...obj};if(type==='projects'&&selectedProjectId===editId)selectedProjectId=obj.id}else data[type].unshift(obj);let record=data[type].find(x=>x.id===obj.id);if(['moulds','parts'].includes(type))syncPartMouldRelations(type,record);if(type==='moulds')ensureMouldRepair(record);if(type==='repairs'){ensureRepairPurchases(record);if(record.status==='Terminé'){let mould=data.moulds.find(m=>m.id===record.mould);if(mould)mould.status='Dispo'}}if(type==='purchases'&&record.status==='Terminé'&&record.repairId){let linked=data.purchases.filter(p=>p.repairId===record.repairId),repair=data.repairs.find(r=>r.id===record.repairId);if(repair&&linked.every(p=>p.status==='Terminé'))repair.status='En réparation'}save();closeModal();view=returnToDetail?'projectDetail':type;filter='Tous';render();toast(editId?'Modification enregistrée':'Enregistrement sauvegardé')};
$('#globalSearch').oninput=()=>{if(!['dashboard','reports'].includes(view))render()};$('#resetBtn').onclick=()=>{if(confirm('Restaurer les données de démonstration ?')){data=structuredClone(seed);save();render();toast('Données restaurées')}};const logoutButtons=[$('#logoutBtn'),$('#sidebarLogoutBtn')];const signOut=async()=>{if(!confirm('Voulez-vous quitter ToolManager et revenir à la page de connexion ?'))return;logoutButtons.forEach(button=>button.disabled=true);await window.MoldCloud?.logout();logoutButtons.forEach(button=>button.disabled=false)};logoutButtons.forEach(button=>button.onclick=signOut);
let appRole=window.MoldCloud?.enabled?'viewer':'admin',currentMemberName='XING ZHAO';const canEdit=()=>appRole==='admin';function applyIdentity(member){if(member?.display_name)currentMemberName=member.display_name;let initials=currentMemberName.split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase();let profileName=$('#profileName'),profileAvatar=$('#profileAvatar'),profileRole=$('#profileRole'),welcome=document.querySelector('.welcome h2');if(profileName)profileName.textContent=currentMemberName;if(profileAvatar)profileAvatar.textContent=initials||'ET';if(profileRole)profileRole.textContent=canEdit()?'Administrateur':'Lecture seule';if(welcome?.firstChild)welcome.firstChild.nodeValue=`Bonjour, ${currentMemberName} `}function applyRoleUi(){let readonly=!canEdit();document.body.classList.toggle('read-only',readonly);document.body.dataset.role=appRole;let mainButton=$('#mainAddBtn');mainButton.hidden=readonly&&view!=='reports';$('#resetBtn').hidden=readonly;document.querySelectorAll('.status-select').forEach(select=>select.disabled=readonly);let roleBadge=$('#roleBadge');if(!roleBadge){roleBadge=document.createElement('div');roleBadge.id='roleBadge';document.body.appendChild(roleBadge)}roleBadge.textContent=readonly?'LECTURE SEULE':'ADMINISTRATEUR';roleBadge.className=readonly?'role-badge readonly':'role-badge admin';applyIdentity()}const renderWithRole=render;render=()=>{renderWithRole();applyRoleUi()};
const mutationSelector='[data-edit],[data-delete],[data-log-project],[data-edit-log],[data-delete-log],[data-stage],[data-edit-project],[data-clear-multi],[data-add-purchase-component],[data-remove-purchase-component],[data-add-repair-component],[data-remove-repair-component],#resetBtn';document.addEventListener('click',e=>{if(canEdit())return;let blocked=e.target.closest(mutationSelector),main=e.target.closest('#mainAddBtn');if(!blocked&&!(main&&view!=='reports'))return;e.preventDefault();e.stopImmediatePropagation();toast('Mode lecture seule · modification interdite')},true);document.addEventListener('change',e=>{if(canEdit()||!e.target.matches('.status-select'))return;e.preventDefault();e.stopImmediatePropagation();render();toast('Mode lecture seule · statut non modifiable')},true);$('#entityForm').addEventListener('submit',e=>{if(canEdit())return;e.preventDefault();e.stopImmediatePropagation();closeModal();toast('Mode lecture seule · enregistrement interdit')},true);
window.addEventListener('toolmanager-role-ready',e=>{appRole=e.detail?.role||'viewer';applyIdentity(e.detail?.member);applyRoleUi()});window.addEventListener('toolmanager-logged-out',()=>{appRole='viewer';applyRoleUi()});window.addEventListener('moldflow-cloud-ready',e=>{if(e.detail){data=e.detail;localStorage.setItem('mouldOpsDataFr',JSON.stringify(data))}else window.MoldCloud?.push(data);render();toast(canEdit()?'Données partagées chargées':'Données chargées · lecture seule')});
render();window.MoldCloud?.start(data).then(remote=>{if(remote&&remote!==data){data=remote;localStorage.setItem('mouldOpsDataFr',JSON.stringify(data));render()}});
